    esgBullet2Title: "Sản xuất có khả năng đạt net-zero",
    esgBullet2Text: " — tế bào sản xuất tương thích với năng lượng mặt trời, hỗ trợ cam kết năng lượng tái tạo phía thượng nguồn chuỗi cung ứng của bạn.",
    esgBullet3Title: "Không phát thải kim loại trong nước thải giặt",
    esgBullet3Text: " — FUZE không rò rỉ theo thiết kế. Đóng góp phía hạ nguồn của bạn vào gánh nặng xử lý nước thành phố từ hoàn tất này = 0.",
    esgBullet4Title: "Không PFAS, không formaldehyde, không chất kết dính",
    esgBullet4Text: " — mọi đầu vào hóa dầu mà các chất truyền thống yêu cầu, FUZE đều loại bỏ.",
    esgBullet5Title: "Tương thích tái chế cơ học và hóa học",
    esgBullet5Text: " — các sản phẩm đã xử lý có thể quay lại các chương trình tuần hoàn của bạn mà không làm ô nhiễm dòng sợi thu hồi.",
    esgBullet6Title: "Tương thích ZDHC MRSL",
    esgBullet6Text: " — không có chất bị gắn cờ. Tương thích với ZDHC Conformance Level 3.",
    methodologyEyebrow: "Ghi chú phương pháp luận",
    methodologyTitle: "Vì sao ASTM E2149 là thử nghiệm hiệu quả chính của FUZE",
    methodologyPara1: "Các nhóm bền vững thương hiệu thường hỏi tại sao thử nghiệm hiệu quả chính của FUZE được báo cáo theo ASTM E2149 thay vì AATCC 100 ở F3 và F4. Câu trả lời ngắn: ASTM E2149 là thử nghiệm tiếp xúc động được thiết kế cho hóa học tiêu diệt qua tiếp xúc không rò rỉ. Nó tưởng thưởng cho sự tiếp xúc vật lý trực tiếp giữa tế bào vi khuẩn và bề mặt sợi liên kết metamaterial — đây chính xác là cơ chế của FUZE.",
    methodologyPara2Lead: "AATCC 100 xếp lớp vải xung quanh một mẫu thử đã cấy và đo các đơn vị hình thành khuẩn lạc sống sót. Nó được thiết kế cho ",
    methodologyPara2Em: "rò rỉ",
    methodologyPara2Suffix: " các chất kháng khuẩn — các hóa chất giải phóng ion vào độ ẩm xung quanh và tiêu diệt vi khuẩn qua trường ion đó. Hình học xếp lớp giúp các hóa chất rò rỉ; các ion được giải phóng bão hòa không gian giữa các lớp.",
    methodologyPara3: "FUZE đạt AATCC 100 ở các hạng cao hơn (F1 và F2) nơi mật độ metamaterial đủ để vượt qua hình học của thử nghiệm. Đối với F3 và F4, thử nghiệm hiệu quả chính phù hợp là ASTM E2149. Các đánh giá thương hiệu nhận được ASTM E2149 trên cả bốn hạng cùng với AATCC 100 ở F1 và F2 như một góc nhìn bổ sung.",
