    esgBullet2: "✓ Sản xuất có khả năng net-zero — tế bào sản xuất tương thích năng lượng mặt trời. Kết hợp với hợp đồng cung cấp năng lượng tái tạo và bước kháng khuẩn đóng góp zero phát thải scope-2.",
